import{_ as a,o as s,c as n,a2 as o}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"构建与打包","description":"","frontmatter":{},"headers":[],"relativePath":"zh/dev/build.md","filePath":"zh/dev/build.md"}'),l={name:"zh/dev/build.md"};function i(t,e,c,d,p,r){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="构建与打包" tabindex="-1">构建与打包 <a class="header-anchor" href="#构建与打包" aria-label="Permalink to &quot;构建与打包&quot;">​</a></h1><p>这里是构建系统的开发者视角。用户级指南见仓库根目录的 <a href="./../root/BUILDING.html">BUILDING.md</a>——本页补充开发者工作流的细节。</p><h2 id="你真正会用的目标" tabindex="-1">你真正会用的目标 <a class="header-anchor" href="#你真正会用的目标" aria-label="Permalink to &quot;你真正会用的目标&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make -j$(nproc) kernel     # fast inner loop: ELF only</span></span>
<span class="line"><span>make iso                   # + bootable ISO</span></span>
<span class="line"><span>make test                  # host unit tests (no QEMU needed)</span></span>
<span class="line"><span>make run-bios              # boot the ISO</span></span>
<span class="line"><span>make clean                 # start fresh</span></span>
<span class="line"><span>make reproducible-check    # two clean builds -&gt; byte-identical ELF</span></span></code></pre></div><h2 id="编译缓存让内循环飞快" tabindex="-1">编译缓存让内循环飞快 <a class="header-anchor" href="#编译缓存让内循环飞快" aria-label="Permalink to &quot;编译缓存让内循环飞快&quot;">​</a></h2><p><code>tools/oc_cc.sh</code> 给每条编译规则包了一层内容寻址缓存： 键 = 编译器身份 + 完整旗标集 + 源文件内容哈希</p><ul><li>每个头文件依赖的内容哈希（依赖探测是一次 <code>gcc -MM -MG</code> 扫描，并剥掉 -MMD/-MP 旗标，让两者互不打架）。</li></ul><ul><li>发布树冷构建：46.6 秒。热构建：14.4 秒（186/186 命中， 3.2 倍提速）。热对象与冷对象逐字节一致。</li><li><code>make cache-stats</code> / <code>make cache-clear</code> 负责管理它。</li><li>过期缓存条目不可能存在：任何头文件改动都会改变键。</li></ul><h2 id="版本号与构建号" tabindex="-1">版本号与构建号 <a class="header-anchor" href="#版本号与构建号" aria-label="Permalink to &quot;版本号与构建号&quot;">​</a></h2><ul><li><code>OC_RELEASE_VERSION</code> 默认取 Makefile 中的 <code>1.0.0</code> 字面量（见 <a href="./../release/versioning.html">版本号规则</a>）；在命令行 覆盖（<code>make OC_RELEASE_VERSION=1.0.1-test1 iso</code>），否则它会 进入横幅、<code>uname -a</code>、OTA 清单与 ISO 卷标。</li><li>构建号是提交计数（<code>git rev-list count</code>）——它供给 <code>uname</code> 以及发布时 update.json 的 &quot;build&quot; 字段。</li></ul><h2 id="打包确定性" tabindex="-1">打包确定性 <a class="header-anchor" href="#打包确定性" aria-label="Permalink to &quot;打包确定性&quot;">​</a></h2><ul><li><strong>SRC zip</strong>（<code>make src-zip</code>）：一次 <code>git archive</code>——目录树 顺序、提交时间戳、索引权限全固定；同一提交产出逐字节一致。 经由 <code>SRC_EXCLUDE</code> 排除 website/out/build/deliverables 树。</li><li><strong>OTA</strong>（<code>make ota</code>）：内核 ELF + 清单；清单携带构建日 （UTC），使包在同一天内逐字节可复现。</li><li><strong>ELF</strong>：全树任何位置都没有 <strong>DATE</strong>/<strong>TIME</strong>/<strong>TIMESTAMP</strong> （一道 make 门禁专门 grep 它们）、链接顺序固定、<code>strip --strip-debug</code> 移除携带路径的节。</li></ul><h2 id="多配置与交叉构建-开发者须知" tabindex="-1">多配置与交叉构建（开发者须知） <a class="header-anchor" href="#多配置与交叉构建-开发者须知" aria-label="Permalink to &quot;多配置与交叉构建（开发者须知）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make defconfig          # .config with everything on</span></span>
<span class="line"><span>make menuconfig         # interactive (tools/oc_menuconfig.sh)</span></span>
<span class="line"><span>make CONFIG_TUI=n CONFIG_CHINESE=n iso    # 216-command image</span></span>
<span class="line"><span>make ARCH=arm64         # PL011 bring-up shell ELF</span></span>
<span class="line"><span>make ARCH=riscv         # NS16550A bring-up shell ELF</span></span></code></pre></div><p>配置器生成带比较保护的宏到 <code>kernel/generated/config_gen.h</code>； 被关闭的特性会路由到真正的 ASCII 等价物（console_cn -&gt; screen_console），而不是删代码。GNU make 的 <code>%</code> 通配符限制 （一条模式里只有第一个 <code>%</code> 生效）正是 TUI/中文源码过滤器长成 那个样子的原因——不要去&quot;简化&quot;它们。</p><h2 id="可脚本化-api" tabindex="-1">可脚本化 API <a class="header-anchor" href="#可脚本化-api" aria-label="Permalink to &quot;可脚本化 API&quot;">​</a></h2><p><code>tools/build.sh</code> 同时是一个函数库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source tools/build.sh</span></span>
<span class="line"><span>build_all; build_iso; config_load; cache_lookup; cross_compile ...</span></span>
<span class="line"><span>tools/build.sh api-selftest     # verifies the 8 spec&#39;d interfaces</span></span></code></pre></div><p>发布自动化（见 <a href="./../release/process.html">../release/process.md</a>） 直接组合这些函数，而不是去解析 make 输出。</p>`,19)])])}const m=a(l,[["render",i]]);export{u as __pageData,m as default};
